content:
:root {
  --primary-color: #4f46e5;
  --primary-hover: #4338ca;
  --bg-color: #f3f4f6;
  --card-bg: #ffffff;
  --text-main: #1f2937;
  --text-muted: #6b7280;
  --border-color: #e5e7eb;
  --danger-color: #ef4444;
  --danger-hover: #dc2626;
  --radius: 8px;
  --transition: 0.2s ease;
}

@media (prefers-color-scheme: dark) {
  :root {
    --primary-color: #6366f1;
    --primary-hover: #4f46e5;
    --bg-color: #111827;
    --card-bg: #1f2937;
    --text-main: #f9fafb;
    --text-muted: #9ca3af;
    --border-color: #374151;
    --danger-color: #f87171;
    --danger-hover: #ef4444;
  }
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  display: flex;
  justify-content: center;
  align-items: flex-start;
  min-height: 100vh;
  padding: 40px 16px;
}

@media (max-width: 480px) {
  body {
    padding: 16px 8px;
  }
  .todo-container {
    padding: 16px;
  }
  .header {
    font-size: 1.25rem;
  }
}

.todo-container {
  background-color: var(--card-bg);
  width: 100%;
  max-width: 500px;
  padding: 24px;
  border-radius: var(--radius);
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  transition: background-color var(--transition), box-shadow var(--transition);
}

.header {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 20px;
  text-align: center;
  color: var(--text-main);
}

.todo-form {
  display: flex;
  gap: 8px;
  margin-bottom: 20px;
}

.todo-input {
  flex: 1;
  padding: 10px 14px;
  font-size: 1rem;
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  outline: none;
  background-color: var(--card-bg);
  color: var(--text-main);
  transition: border-color var(--transition), background-color var(--transition), color var(--transition);
}

.todo-input:focus {
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.1);
}

.btn {
  padding: 10px 16px;
  font-size: 1rem;
  font-weight: 500;
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  transition: background-color var(--transition), transform 0.1s ease;
}

.btn:active {
  transform: scale(0.98);
}

.btn-primary {
  background-color: var(--primary-color);
  color: #ffffff;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

.todo-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(-8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.todo-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 14px;
  background-color: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  animation: fadeIn 0.25s ease-out;
  transition: background-color var(--transition), border-color var(--transition), transform var(--transition);
}

.todo-item:hover {
  background-color: rgba(0, 0, 0, 0.02);
}

.todo-checkbox {
  width: 18px;
  height: 18px;
  cursor: pointer;
  accent-color: var(--primary-color);
}

.todo-text {
  flex: 1;
  margin-left: 12px;
  font-size: 1rem;
  color: var(--text-main);
  word-break: break-all;
  transition: color var(--transition);
}

.todo-item.completed .todo-text {
  text-decoration: line-through;
  color: var(--text-muted);
}

.todo-delete {
  background-color: transparent;
  color: var(--danger-color);
  padding: 6px 10px;
  font-size: 0.875rem;
}

.todo-delete:hover {
  background-color: rgba(239, 68, 68, 0.1);
  color: var(--danger-hover);
  border-radius: var(--radius);
}

.empty-message {
  text-align: center;
  color: var(--text-muted);
  padding: 24px 0;
  font-size: 0.95rem;
}

export interface TodoItem {
  id: string;
  text: string;
  completed: boolean;
}

export type FilterType = 'all' | 'active' | 'completed';

export interface TodoFormProps {
  onAdd: (text: string) => void;
}

export interface TodoListProps {
  todos: TodoItem[];
  onToggle: (id: string) => void;
  onDelete: (id: string) => void;
  onEdit?: (id: string, text: string) => void;
}

export interface TodoItemProps {
  todo: TodoItem;
  onToggle: (id: string) => void;
  onDelete: (id: string) => void;
  onEdit?: (id: string, text: string) => void;
}

import { useState, type FormEvent } from 'react';
import type { TodoFormProps } from './types';

export default function TodoForm({ onAdd }: TodoFormProps) {
  const [text, setText] = useState('');
  const [error, setError] = useState('');

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    if (!text.trim()) {
      setError('タスクを入力してください');
      return;
    }
    onAdd(text.trim());
    setText('');
    setError('');
  };

  return (
    <div>
      <form className="todo-form" onSubmit={handleSubmit}>
        <input
          type="text"
          className="todo-input"
          placeholder="新しいタスクを入力..."
          value={text}
          maxLength={100}
          onChange={(e) => {
            setText(e.target.value);
            if (error) setError('');
          }}
          aria-label="新しいタスク"
        />
        <button type="submit" className="btn btn-primary">
          追加
        </button>
      </form>
      {error && (
        <div style={{ color: 'var(--danger-color)', fontSize: '0.875rem', marginBottom: '12px' }}>
          {error}
        </div>
      )}
    </div>
  );
}

import { useState, type KeyboardEvent } from 'react';
import type { TodoItemProps } from './types';

export default function TodoItem({ todo, onToggle, onDelete }: TodoItemProps) {
  const [isEditing, setIsEditing] = useState(false);
  const [editText, setEditText] = useState(todo.text);

  const handleKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      if (editText.trim()) {
        setIsEditing(false);
      }
    } else if (e.key === 'Escape') {
      setEditText(todo.text);
      setIsEditing(false);
    }
  };

  return (
    <li className={`todo-item ${todo.completed ? 'completed' : ''}`}>
      <input
        type="checkbox"
        className="todo-checkbox"
        checked={todo.completed}
        onChange={() => onToggle(todo.id)}
        aria-label={`${todo.text}を完了にする`}
      />
      {isEditing ? (
        <input
          type="text"
          className="todo-input"
          value={editText}
          onChange={(e) => setEditText(e.target.value)}
          onBlur={() => setIsEditing(false)}
          onKeyDown={handleKeyDown}
          autoFocus
          maxLength={100}
          aria-label="タスクの編集"
        />
      ) : (
        <span
          className="todo-text"
          onDoubleClick={() => setIsEditing(true)}
          tabIndex={0}
          onKeyDown={(e) => {
            if (e.key === 'Enter' || e.key === ' ') {
              setIsEditing(true);
            }
          }}
          role="button"
          aria-label="ダブルクリックまたはEnterキーでタスクを編集"
        >
          {todo.text}
        </span>
      )}
      <button
        type="button"
        className="btn todo-delete"
        onClick={() => onDelete(todo.id)}
        aria-label={`${todo.text}を削除`}
      >
        削除
      </button>
    </li>
  );
}

import { useState, useEffect } from 'react';
import type { TodoListProps, FilterType } from './types';
import TodoItem from './TodoItem';

export default function TodoList({ todos = [], onToggle, onDelete }: TodoListProps) {
  const [filter, setFilter] = useState<FilterType>('all');
  const [localTodos, setLocalTodos] = useState(todos);

  useEffect(() => {
    setLocalTodos(todos);
  }, [todos]);

  const moveTodo = (id: string, direction: 'up' | 'down') => {
    const index = localTodos.findIndex((t) => t.id === id);
    if (index === -1) return;
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex < 0 || targetIndex >= localTodos.length) return;
    const newTodos = [...localTodos];
    const [removed] = newTodos.splice(index, 1);
    newTodos.splice(targetIndex, 0, removed);
    setLocalTodos(newTodos);
  };

  const filteredTodos = localTodos.filter((todo) => {
    if (filter === 'active') return !todo.completed;
    if (filter === 'completed') return todo.completed;
    return true;
  });

  return (
    <div>
      <div style={{ display: 'flex', gap: '8px', marginBottom: '16px', justifyContent: 'center' }}>
        <button
          type="button"
          className={`btn ${filter === 'all' ? 'btn-primary' : ''}`}
          style={{
            padding: '6px 12px',
            fontSize: '0.875rem',
            backgroundColor: filter === 'all' ? undefined : 'var(--border-color)',
            color: filter === 'all' ? undefined : 'var(--text-main)',
          }}
          onClick={() => setFilter('all')}
        >
          すべて
        </button>
        <button
          type="button"
          className={`btn ${filter === 'active' ? 'btn-primary' : ''}`}
          style={{
            padding: '6px 12px',
            fontSize: '0.875rem',
            backgroundColor: filter === 'active' ? undefined : 'var(--border-color)',
            color: filter === 'active' ? undefined : 'var(--text-main)',
          }}
          onClick={() => setFilter('active')}
        >
          未完了
        </button>
        <button
          type="button"
          className={`btn ${filter === 'completed' ? 'btn-primary' : ''}`}
          style={{
            padding: '6px 12px',
            fontSize: '0.875rem',
            backgroundColor: filter === 'completed' ? undefined : 'var(--border-color)',
            color: filter === 'completed' ? undefined : 'var(--text-main)',
          }}
          onClick={() => setFilter('completed')}
        >
          完了済み
        </button>
      </div>

      {filteredTodos.length === 0 ? (
        <div className="empty-message">
          {filter === 'active'
            ? '未完了のタスクはありません'
            : filter === 'completed'
            ? '完了済みのタスクはありません'
            : 'タスクがありません'}
        </div>
      ) : (
        <ul className="todo-list">
          {filteredTodos.map((todo) => {
            const originalIndex = localTodos.findIndex((t) => t.id === todo.id);
            return (
              <div key={todo.id} style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
                <div style={{ display: 'flex', flexDirection: 'column', gap: '2px' }}>
                  <button
                    type="button"
                    className="btn"
                    style={{ padding: '2px 6px', fontSize: '0.75rem', backgroundColor: 'var(--border-color)', color: 'var(--text-main)' }}
                    onClick={() => moveTodo(todo.id, 'up')}
                    disabled={originalIndex === 0}
                    aria-label="上に移動"
                  >
                    ▲
                  </button>
                  <button
                    type="button"
                    className="btn"
                    style={{ padding: '2px 6px', fontSize: '0.75rem', backgroundColor: 'var(--border-color)', color: 'var(--text-main)' }}
                    onClick={() => moveTodo(todo.id, 'down')}
                    disabled={originalIndex === localTodos.length - 1}
                    aria-label="下に移動"
                  >
                    ▼
                  </button>
                </div>
                <div style={{ flex: 1 }}>
                  <TodoItem
                    todo={todo}
                    onToggle={onToggle}
                    onDelete={onDelete}
                  />
                </div>
              </div>
            );
          })}
        </ul>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import type { TodoItem } from './types';
import TodoForm from './TodoForm';
import TodoList from './TodoList';
import './index.css';

export default function App() {
  const [todos, setTodos] = useState<TodoItem[]>(() => {
    const saved = localStorage.getItem('todos');
    if (saved) {
      try {
        return JSON.parse(saved);
      } catch (e) {
        console.error(e);
      }
    }
    return [
      { id: '1', text: 'Reactのプロジェクトを作成する', completed: true },
      { id: '2', text: 'やることリストのデザインを整える', completed: false },
      { id: '3', text: 'タスクの追加・削除機能を実装する', completed: false },
    ];
  });

  useEffect(() => {
    localStorage.setItem('todos', JSON.stringify(todos));
  }, [todos]);

  const handleAdd = (text: string) => {
    const newTodo: TodoItem = {
      id: Date.now().toString(),
      text,
      completed: false,
    };
    setTodos([newTodo, ...todos]);
  };

  const handleToggle = (id: string) => {
    setTodos(
      todos.map((todo) =>
        todo.id === id ? { ...todo, completed: !todo.completed } : todo
      )
    );
  };

  const handleDelete = (id: string) => {
    setTodos(todos.filter((todo) => todo.id !== id));
  };

  const handleClearCompleted = () => {
    setTodos(todos.filter((todo) => !todo.completed));
  };

  const activeCount = todos.filter((todo) => !todo.completed).length;

  return (
    <div className="todo-container">
      <h1 className="header">やることリスト</h1>
      <div
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          marginBottom: '16px',
          fontSize: '0.875rem',
          color: 'var(--text-muted)',
        }}
      >
        <span>未完了: {activeCount}件 / 総数: {todos.length}件</span>
        {todos.some((t) => t.completed) && (
          <button
            type="button"
            className="btn"
            style={{
              padding: '4px 8px',
              fontSize: '0.875rem',
              backgroundColor: 'transparent',
              color: 'var(--danger-color)',
            }}
            onClick={handleClearCompleted}
          >
            完了済みをクリア
          </button>
        )}
      </div>
      <TodoForm onAdd={handleAdd} />
      <TodoList todos={todos} onToggle={handleToggle} onDelete={handleDelete} />
    </div>
  );
}
